{
  "summary": "During the incident on 18 March 2025 payments-api-03 emitted about 40 PAYAPI-W0310 logs per second while fraud-scorer-01 ran at 45% CPU average but experienced 30% throttled periods.",
  "likely_cause": "CPU throttling on fraud-scorer-01 caused by 16 gunicorn workers (WEB_CONCURRENCY unset) exceeding the pod's CPU limit.",
  "confidence": "high",
  "claims": [
    {
      "text": "payments-api-03 logged about 40 PAYAPI-W0310 messages per second",
      "evidence_ids": ["RB-002#3"],
      "quote": "payments-api-03.prod.internal was logging W0310 at about 40 per second"
    },
    {
      "text": "fraud-scorer-01 showed 30% throttled periods and only 45% average CPU",
      "evidence_ids": ["RB-002#3"],
      "quote": "fraud-scorer-01.prod.internal showed 30% throttled periods and only 45% average CPU"
    },
    {
      "text": "WEB_CONCURRENCY was unset, causing 16 gunicorn workers which exceeded the CPU limit",
      "evidence_ids": ["INC-0024#2"],
      "quote": "`WEB_CONCURRENCY` was unset in the Deployment, so the entrypoint had counted the cores it could see, all 16 of the node, and started a worker for each"
    }
  ],
  "next_checks": [
    "Verify the current WEB_CONCURRENCY setting and worker count for fraud-scorer pods",
    "Check container_cpu_cfs_throttled_periods_total metric for ongoing throttling",
    "Confirm GOMAXPROCS is set from the container CPU limit"
  ]
}
